/* Hidden attribute safeguard */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #141026;
  --color-card: #2b2353;
  --color-accent: #ffcb38;
  --color-text: #f4f4f4;
  --color-text-dim: #9b93c8;
  --color-danger: #ff4766;
  --color-border: #0c0919;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--color-bg);
  /* Pixel grid pattern using pure CSS */
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 1px);
  background-size: 16px 16px;
  color: var(--color-text);
  font-family: "Courier New", Courier, monospace, system-ui, sans-serif;
  font-size: 16px;
  line-height: 1.4;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.quiz-card {
  background-color: var(--color-card);
  width: 100%;
  max-width: 520px;
  border: 4px solid var(--color-border);
  box-shadow:
    6px 6px 0 var(--color-border),
    inset -3px -3px 0 rgba(0, 0, 0, 0.4),
    inset 3px 3px 0 rgba(255, 255, 255, 0.15);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.quiz-header {
  display: flex;
  flex-direction: column;
  gap: 12px;
  border-bottom: 3px dashed var(--color-text-dim);
  padding-bottom: 16px;
}

.quiz-title {
  font-size: 24px;
  text-align: center;
  letter-spacing: 2px;
  color: var(--color-accent);
  text-shadow: 2px 2px 0 var(--color-border);
}

.status-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 18px;
  font-weight: bold;
}

.status-item {
  display: flex;
  align-items: center;
  gap: 6px;
  background: var(--color-border);
  padding: 6px 12px;
  border: 2px solid var(--color-text-dim);
}

.status-label {
  color: var(--color-text-dim);
  font-size: 14px;
}

.status-value {
  color: var(--color-accent);
  font-size: 20px;
  min-width: 28px;
  text-align: right;
}

.time-warning {
  color: var(--color-danger) !important;
  animation: pulse 1s infinite alternate;
}

@keyframes pulse {
  0% { transform: scale(1); }
  100% { transform: scale(1.08); }
}

.progress-track {
  height: 8px;
  background-color: var(--color-border);
  border: 1px solid var(--color-text-dim);
  width: 100%;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background-color: var(--color-accent);
  width: 100%;
  transition: width 0.25s linear;
}

.screen {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.badge {
  display: inline-block;
  background-color: var(--color-border);
  color: var(--color-accent);
  padding: 4px 10px;
  font-size: 14px;
  font-weight: bold;
  border-left: 4px solid var(--color-accent);
}

.question-text {
  font-size: 19px;
  font-weight: bold;
  min-height: 52px;
  color: #ffffff;
}

.answers-grid {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.pixel-btn {
  display: block;
  width: 100%;
  padding: 14px 16px;
  background-color: #3b316f;
  color: var(--color-text);
  font-family: inherit;
  font-size: 16px;
  font-weight: bold;
  text-align: left;
  cursor: pointer;
  border: 3px solid var(--color-border);
  box-shadow:
    3px 3px 0 var(--color-border),
    inset 1px 1px 0 rgba(255, 255, 255, 0.2);
  outline: none;
  transition: background-color 0.1s, transform 0.05s;
}

.pixel-btn:hover {
  background-color: #493d8b;
  color: #ffffff;
}

.pixel-btn:focus-visible {
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px var(--color-accent), 3px 3px 0 var(--color-border);
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0 var(--color-border);
}

.result-box {
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 12px 0;
}

.result-title {
  font-size: 26px;
  letter-spacing: 2px;
  color: var(--color-accent);
}

.result-reason {
  color: var(--color-text-dim);
  font-size: 16px;
}

.final-score-display {
  background: var(--color-border);
  padding: 18px;
  border: 2px solid var(--color-text-dim);
  display: flex;
  flex-direction: column;
  gap: 6px;
  align-items: center;
}

.final-score-label {
  font-size: 14px;
  letter-spacing: 1px;
  color: var(--color-text-dim);
}

.final-score-number {
  font-size: 36px;
  font-weight: bold;
  color: var(--color-accent);
}

.btn-restart {
  text-align: center;
  background-color: var(--color-accent);
  color: var(--color-border);
  margin-top: 8px;
  font-size: 18px;
}

.btn-restart:hover {
  background-color: #ffd866;
  color: var(--color-border);
}

@media (max-width: 420px) {
  .quiz-card {
    padding: 16px;
  }
  .quiz-title {
    font-size: 20px;
  }
  .question-text {
    font-size: 17px;
  }
  .pixel-btn {
    padding: 12px 14px;
    font-size: 15px;
  }
}

const QUIZ_QUESTIONS = [
  {
    question: "What does CSS stand for?",
    options: [
      "Cascading Style Sheets",
      "Creative Styling System",
      "Computer System Standards",
      "Coded Simple Syntax"
    ],
    correct: 0
  },
  {
    question: "Which HTML element contains JavaScript?",
    options: ["<javascript>", "<script>", "<js>", "<code>"],
    correct: 1
  },
  {
    question: "How do you output messages to the web console?",
    options: [
      "console.write()",
      "print()",
      "console.log()",
      "system.out.print()"
    ],
    correct: 2
  },
  {
    question: "Which keyword declares a block-scoped constant?",
    options: ["var", "let", "immutable", "const"],
    correct: 3
  },
  {
    question: "Which event fires when clicking an element?",
    options: ["click", "touchmove", "submit", "hover"],
    correct: 0
  }
];

const TOTAL_TIME = 60;
let timerRemaining = TOTAL_TIME;
let timerInterval = null;
let currentIndex = 0;
let score = 0;

const timerValueEl = document.getElementById("timer-value");
const timerContainerEl = document.getElementById("timer-container");
const progressBarEl = document.getElementById("time-progress-bar");
const scoreValueEl = document.getElementById("score-value");
const questionScreenEl = document.getElementById("question-screen");
const resultScreenEl = document.getElementById("result-screen");
const questionNumberEl = document.getElementById("question-number");
const questionTextEl = document.getElementById("question-text");
const answersContainerEl = document.getElementById("answers-container");
const resultHeadingEl = document.getElementById("result-heading");
const resultReasonEl = document.getElementById("result-reason");
const finalScoreValueEl = document.getElementById("final-score-value");
const btnRestart = document.getElementById("btn-restart");

function startTimer() {
  clearInterval(timerInterval);
  timerRemaining = TOTAL_TIME;
  updateTimerDisplay();

  timerInterval = setInterval(() => {
    timerRemaining--;
    updateTimerDisplay();

    if (timerRemaining <= 0) {
      endQuiz("Time expired!");
    }
  }, 1000);
}

function updateTimerDisplay() {
  timerValueEl.textContent = timerRemaining;
  const percent = Math.max(0, (timerRemaining / TOTAL_TIME) * 100);
  progressBarEl.style.width = percent + "%";

  if (timerRemaining <= 10) {
    timerContainerEl.classList.add("time-warning");
  } else {
    timerContainerEl.classList.remove("time-warning");
  }
}

function displayQuestion() {
  const current = QUIZ_QUESTIONS[currentIndex];
  questionNumberEl.textContent = `QUESTION ${currentIndex + 1}/${QUIZ_QUESTIONS.length}`;
  questionTextEl.textContent = current.question;
  answersContainerEl.innerHTML = "";

  current.options.forEach((optText, optIdx) => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "pixel-btn";
    btn.textContent = `${String.fromCharCode(65 + optIdx)}) ${optText}`;
    btn.setAttribute("data-index", optIdx);
    btn.addEventListener("click", () => handleAnswer(optIdx));
    answersContainerEl.appendChild(btn);
  });

  // Auto focus first option for keyboard accessibility
  const firstOption = answersContainerEl.querySelector("button");
  if (firstOption) {
    firstOption.focus();
  }
}

function handleAnswer(selectedIndex) {
  if (selectedIndex === QUIZ_QUESTIONS[currentIndex].correct) {
    score++;
    scoreValueEl.textContent = score;
  }

  currentIndex++;
  if (currentIndex < QUIZ_QUESTIONS.length) {
    displayQuestion();
  } else {
    endQuiz("All questions answered!");
  }
}

function endQuiz(reason) {
  clearInterval(timerInterval);
  questionScreenEl.hidden = true;
  resultScreenEl.hidden = false;

  resultHeadingEl.textContent = score >= 3 ? "VICTORY!" : "QUIZ OVER";
  resultReasonEl.textContent = reason;
  finalScoreValueEl.textContent = `${score} / ${QUIZ_QUESTIONS.length}`;

  btnRestart.focus();
}

function initGame() {
  currentIndex = 0;
  score = 0;
  scoreValueEl.textContent = score;
  questionScreenEl.hidden = false;
  resultScreenEl.hidden = true;
  displayQuestion();
  startTimer();
}

btnRestart.addEventListener("click", initGame);

// Start game upon initial load
initGame();
